<?php
$item=is_array($item??null)?$item:[];$editing=!empty($editing);
$prefLink=is_array($preferred_supplier_link??null)?$preferred_supplier_link:[];
$errors=is_array(session('errors'))?session('errors'):[];
$value=static function(string $name,$default='')use($item):string{$v=old($name,$item[$name]??$default);return is_scalar($v)?(string)$v:'';};
$mappingDefaults=['supplier_sku'=>$prefLink['supplier_sku']??'','pack_size_label'=>$prefLink['pack_size_label']??'','preferred_order_qty'=>$prefLink['preferred_order_qty']??'','supplier_last_unit_price'=>$prefLink['last_unit_price']??'','supplier_price_currency'=>$prefLink['currency']??'ILS'];
$field=static function(string $name,string $label,string $type='text',string $attributes='', $default='')use($value,$errors):void{ ?>
    <div class="form-field"><label for="<?= esc($name,'attr') ?>"><?= esc(lang('Inventory.'.$label)) ?></label><input id="<?= esc($name,'attr') ?>" name="<?= esc($name,'attr') ?>" type="<?= esc($type,'attr') ?>" value="<?= esc($value($name,$default),'attr') ?>" <?= $attributes ?> aria-invalid="<?= isset($errors[$name])?'true':'false' ?>" <?= isset($errors[$name])?'aria-describedby="'.$name.'-error"':'' ?>><?php if(isset($errors[$name])): ?><p class="field-error" id="<?= esc($name,'attr') ?>-error"><?= esc($errors[$name]) ?></p><?php endif; ?></div>
<?php };
$categories=$editing?($categories??[]):['medication'=>lang('Inventory.categoryMedication'),'equipment'=>lang('Inventory.categoryEquipment'),'supplies'=>lang('Inventory.categorySupplies'),'consumables'=>lang('Inventory.categoryConsumables'),'other'=>lang('Inventory.categoryOther')];
?>
<section class="form-section"><header><h2><?= esc(lang('Studio.itemIdentity')) ?></h2></header><div class="item-identity-grid">
    <?php $field('item_name','itemNameRequired','text','required'); ?>
    <div class="form-field"><label for="category"><?= esc(lang('Inventory.categoryRequired')) ?></label><select id="category" name="category" data-force-select2 data-allow-clear="false" required><option value=""><?= esc(lang('Inventory.selectCategory')) ?></option><?php foreach($categories as $key=>$label): ?><option value="<?= esc($key,'attr') ?>" <?= $value('category')===(string)$key?'selected':'' ?>><?= esc($label) ?></option><?php endforeach; ?></select></div>
    <?php if($editing): ?><div class="form-field"><label for="status"><?= esc(lang('Inventory.statusRequired')) ?></label><select id="status" name="status" data-force-select2 data-allow-clear="false" required><?php foreach(['active'=>'statusActive','inactive'=>'statusInactive','discontinued'=>'statusDiscontinued'] as $key=>$label): ?><option value="<?= $key ?>" <?= $value('status')===$key?'selected':'' ?>><?= esc(lang('Inventory.'.$label)) ?></option><?php endforeach; ?></select></div><?php endif; ?>
</div><div class="form-field item-description"><label for="description"><?= esc(lang('Inventory.description')) ?></label><textarea id="description" name="description" rows="2"><?= esc($value('description')) ?></textarea></div></section>
<section class="form-section"><header><h2><?= esc(lang('Studio.stockAndPrice')) ?></h2></header><div class="item-stock-grid">
    <?php if($editing): ?><input type="hidden" name="expected_quantity" value="<?= esc($value('expected_quantity',$item['quantity']??''),'attr') ?>"><?php endif; ?>
    <?php $field('quantity','quantityRequired','number','min="0" step="1" required');$field('min_quantity','minimumQuantityRequired','number','min="0" step="1" required'); ?>
    <div class="form-field"><label for="unit"><?= esc(lang('Inventory.unit')) ?></label><select id="unit" name="unit" data-force-select2 data-allow-clear="false"><?php foreach(['pieces','boxes','bottles','tubes','packs','sets'] as $unit): ?><option value="<?= $unit ?>" <?= $value('unit','pieces')===$unit?'selected':'' ?>><?= esc(lang('Inventory.unit'.ucfirst($unit))) ?></option><?php endforeach; ?></select></div>
    <?php $field('unit_price','unitPriceRequired','number','min="0" step="0.01" required'); ?>
</div></section>
<section class="form-section"><header class="item-supplier-heading"><h2><?= esc(lang('Inventory.supplier')) ?></h2><div><a class="button secondary" href="<?= base_url('providers') ?>" target="_blank" rel="noopener"><?= esc(lang('Inventory.manageSuppliers')) ?></a><?php if(has_permission('inventory','edit')): ?><button class="button secondary" type="button" data-dialog="item-supplier-dialog"><?= esc(lang('Inventory.quickAdd')) ?></button><?php endif; ?></div></header><div class="form-grid">
    <div class="form-field"><label for="supplier_id"><?= esc(lang('Inventory.supplierDirectory')) ?></label><select id="supplier_id" name="supplier_id" data-force-select2 data-allow-clear="false"><option value=""><?= esc(lang('Inventory.noLinkedSupplier')) ?></option><?php foreach($supplier_directory??[] as $supplier): ?><option value="<?= (int)$supplier['id'] ?>" <?= $value('supplier_id')===(string)$supplier['id']?'selected':'' ?>><?= esc($supplier['name']) ?></option><?php endforeach; ?></select></div>
    <?php $field('supplier','customSupplierNameOptional'); ?>
</div><details class="item-mapping" <?= $prefLink||old('supplier_sku')||old('preferred_order_qty')?'open':'' ?>><summary><?= esc(lang('Studio.supplierTerms')) ?></summary><div class="item-mapping-grid">
<?php foreach(['supplier_sku'=>'supplierSku','pack_size_label'=>'packSize','preferred_order_qty'=>'preferredReorderQty','supplier_last_unit_price'=>'lastSupplierPrice'] as $name=>$label):$numeric=in_array($name,['preferred_order_qty','supplier_last_unit_price'],true);$field($name,$label,$numeric?'number':'text',$name==='preferred_order_qty'?'min="1" step="1"':($name==='supplier_last_unit_price'?'min="0" step="0.01"':''),$mappingDefaults[$name]);endforeach; ?>
<div class="form-field"><label for="supplier_price_currency"><?= esc(lang('Finance.currency')) ?></label><select id="supplier_price_currency" name="supplier_price_currency" data-force-select2 data-allow-clear="false"><?php foreach($currencies??['ILS'] as $currency): ?><option value="<?= esc($currency,'attr') ?>" <?= $value('supplier_price_currency',$mappingDefaults['supplier_price_currency'])===$currency?'selected':'' ?>><?= esc($currency) ?></option><?php endforeach; ?></select></div>
</div></details></section>
<section class="form-section"><header><h2><?= esc(lang('Inventory.additionalInformation')) ?></h2></header><div class="item-dates-grid">
<?php foreach(['purchase_date'=>'purchaseDate','expiry_date'=>'expiryDate'] as $name=>$label):$date=$value($name,$name==='purchase_date'&&!$editing?date('Y-m-d'):'');$iso=$date;if($date!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$parsed=\DateTimeImmutable::createFromFormat('!'.settings()->get('date_format','d/m/Y'),$date);$checks=\DateTimeImmutable::getLastErrors();$iso=$parsed&&(!$checks||(!$checks['warning_count']&&!$checks['error_count']))?$parsed->format('Y-m-d'):'';} ?>
<div class="form-field"><label for="<?= $name ?>"><?= esc(lang('Inventory.'.$label)) ?></label><input id="<?= $name ?>" name="<?= $name ?>" type="date" data-clinic-date="1" value="<?= esc($iso,'attr') ?>"><?php if($date!==''&&$iso===''): ?><p class="field-error"><?= esc(lang('Studio.previousEntry',['value'=>$date])) ?></p><?php endif; ?></div>
<?php endforeach;$field('location','storageLocation'); ?>
